import numpy as npimport matplotlib.pyplot as pltimport timeimport scipy.optimize as spo def reflected_unit_vector(theta_s, R_m, Hdip, theta_ff, phi_ff):                '''                This function not being used                 '''        # phi angle at hit point on the sphere is the same as desired phi angle in the far field        phi_s = np.copy(phi_ff)                        # unit vector normal at hit point on sphere        r_hit = R_m * np.array([np.sin(theta_s)*np.cos(phi_s), np.sin(theta_s)*np.sin(phi_s), np.cos(theta_s)])        n_hat = r_hit / R_m                # vector from center of the moon to location of the antenna        z_prime  = R_m + Hdip        r_dip    = np.array([0, 0, z_prime])                        # unit incident vector hitting the sphere coming from the antenna        k_inc = (r_hit - r_dip) / np.linalg.norm(r_hit - r_dip)                # unit reflected vector        k_refl = k_inc - 2*(np.dot(k_inc, n_hat))*n_hat                # desired unit vector in the far field        R_hat_ff = np.array([np.sin(theta_ff)*np.cos(phi_ff), np.sin(theta_ff)*np.sin(phi_ff), np.cos(theta_ff)])                 # difference between evaluated and desired unit vectors        diff = k_refl - R_hat_ff                # metric: norm of difference vector        metric = np.linalg.norm(diff)                return metricdef theta_of_reflected_ray_far_field(theta_s, R_m, Hdip): #, theta_ff, phi_ff):                '''                theta_s: Theta of hit point on the surface        R_m:     Radius of the moon        H_dip:   Height of dipole                        '''                theta_s_max = np.arccos(R_m/(R_m+Hdip))        #print(str(theta_s_max*(180/np.pi)) + ' ' + str(theta_s*(180/np.pi)))                # Reflection can only be computed up to theta_s_max        if theta_s < theta_s_max:                           # Law of cosines (computing side of triangle between antenna and moon hit point)                a = np.sqrt((R_m+Hdip)**2 + R_m**2 - 2*R_m*(R_m+Hdip)*np.cos(theta_s))                                # Law of sines                # Our geometry corresponds to "the ambiguous case of triangle solution", https://en.wikipedia.org/wiki/Law_of_sines                # Therefore, the angle inside the triangle has to be computed as pi - xxxxx.                y = np.pi - np.arcsin(((R_m+Hdip)/a)*np.sin(theta_s))                                q = np.pi - y                       theta_refl_ff = theta_s + q                                #print(a)                #print(y*(180/np.pi))                #print(q*(180/np.pi))                #print(theta_x*(180/np.pi))                        else:                print('Reflections cannot be computed for theta_s >= theta_s_max')                theta_refl_ff = -1                return theta_refl_ffdef fit_theta_of_reflected_ray_far_field(theta_s, R_m, Hdip, theta_ff):                theta_refl_ff = theta_of_reflected_ray_far_field(theta_s, R_m, Hdip)                diff = theta_refl_ff - theta_ff               return diffdef decompose_sp(E, r_i, r_m):                '''        See QUESTION below                '''                                eps_small = 1e-12                r_i = r_i / np.linalg.norm(r_i)        r_m = r_m / np.linalg.norm(r_m)                # S unit vector (perpendicular to plane of incidence, which is the plane that contains r_i and r_m)        s = np.cross(r_i, r_m)                # If the vectors are (almost) parallel and the cross product is very small        if np.linalg.norm(s) < eps_small:                                # Near-normal incidence                                # QUESTION: Please more details about these two conditions, situations, and the evalue 0.9                                # If plane of incidence is more aligned with x-axis                if abs(np.dot(r_m, np.array([1,0,0]))) < 0.9:                        s = np.cross(r_i, np.array([1,0,0]))                                                        else:                        # If plane of incidence is more aligned with y-axis                        s = np.cross(r_i, np.array([0,1,0]))                                s_hat = s / np.linalg.norm(s)                # P unit vector (in plane of incidence, which is the plane that contains r_i and r_m)        p = np.cross(s, r_i)        p_hat = p / np.linalg.norm(p)                        # S and P projections of the electric field        # 3 cartesian componenents added up to form the S and P projections        E_s = np.sum(s_hat*E, axis=1)        E_p = np.sum(p_hat*E, axis=1)                                # Fix from Aditya, applied here on 2026-02-24        # P unit vector of reflected wave (as opposed of incoming wave)        # Relative to the incoming P unit vector, this vector is mirrored relative to the normal vector, and then its sign is inverted        p_hat_refl = -(2*np.dot(p_hat, r_m)*r_m - p_hat)                                out = {                'E_s'   :E_s,                'E_p'   :E_p,                's_hat' :s_hat,                'p_hat_refl' :p_hat_refl        }                return outdef fresnel_coeff(eta_i, eta_j, cos_theta_i, cos_theta_j, pol):                        # Fresnel coefficients        # "Microwave Radar and Radiometric Remote Sensing", Ulaby and Long, 2014, Tables 2-5, 2-6        # "Balanis' Advanced Engineering Electromagnetics", Balanis, 2024, Eqn 5-17a,b and Eqn 5.24c,d        if pol == 's':                r = (eta_j * cos_theta_i - eta_i * cos_theta_j) / (eta_j * cos_theta_i + eta_i * cos_theta_j)                t = (2 * eta_j * cos_theta_i) / (eta_j * cos_theta_i + eta_i * cos_theta_j)                        elif pol =='p':                r = (eta_j * cos_theta_j - eta_i * cos_theta_i) / (eta_j * cos_theta_j + eta_i * cos_theta_i)                t = (2 * eta_j * cos_theta_i) / (eta_j * cos_theta_j + eta_i * cos_theta_i)        out = {                'r': r,                't': t                }                return out                                def transmission_angle_lossy_medium(f_range, eps_lossless_medium, eps_lossy_medium, theta_i):                '''                THIS FUNCTION IS NOT USED BY THE MAIN CODE. IT IS ONLY PROVIDED FOR REFERENCE.                This function implements the equation for the real angle of the wave transmitted into a lossy medium, which is incident from a lossless medium.        The equation is taken from the end of section 2-9 of the book:        "Microwave Radar and Radiometric Remote Sensing", Ulaby and Long, 2014                        Inputs:        -------        f_range:             (scalar or 1D numpy array) Frequency [Hz].        eps_lossless_medium: (scalar or 1D numpy array) Complex absolute permittivity of the lossless medium [F/m]. Although in general it is complex, for a lossless medium it is purely real.        eps_lossy_medium:    (scalar or 1D numpy array) Complex absolute permittivity of the lossy medium [F/m].    For the lossy medium it has real and imaginary parts.        theta_i:             (scalar) Incident angle from the lossless medium [rad]. Should be in the range [0,np.pi/2].                        Output:        -------        real_angle:          (scalar) Real angle of the wave transmitted into a lossy medium [rad].                        '''                                        # Constants        mu0   = 4*np.pi*1e-7        omega = 2*np.pi*f_range                # Real and imaginary parts of complex absolute permittivity        # eps = eps_2prime + 1j*eps_2prime, or        # eps = eps_2prime - 1j*eps_2prime                        # This python function can support both formalisms because the imaginary part gets squared        eps_1prime = np.real(eps_lossy_medium)        eps_2prime = np.imag(eps_lossy_medium)                        # Wavenumber of lossless medium        k_lossless_medium = omega * np.sqrt(mu0 * np.real(eps_lossless_medium))   # Making sure that permittivity of the lossless medium is real                                # Alpha and beta components of the propagation constant in lossy medium        X1 = 1 + (eps_2prime / eps_1prime)**2                X2_alpha = (mu0 * eps_1prime / 2) * (np.sqrt(X1) - 1)        X2_beta  = (mu0 * eps_1prime / 2) * (np.sqrt(X1) + 1)                alpha = omega * np.sqrt(X2_alpha)        beta  = omega * np.sqrt(X2_beta)                        # Real transmission angle        numerator   = np.sqrt(2) * k_lossless_medium * np.sin(theta_i)        p = 2 * alpha * beta        q = beta**2 - alpha**2 - (k_lossless_medium**2) * (np.sin(theta_i)**2)        denominator = np.sqrt(q + np.sqrt(p**2 + q**2))        real_angle  = np.arctan(numerator / denominator) # Angle is always positive, we do not need to use arctan2                        return real_angle                        def total_reflection_three_layers(f_range, eps_0, eps_1, eps_2, theta_i, d, pol):                '''                        '''                                # Constants        c     = 299792458 # m/s        mu0   = 4*np.pi*1e-7        omega = 2*np.pi*f_range                # Wave impedance of each medium        eta_0 = np.sqrt(mu0 / eps_0)        eta_1 = np.sqrt(mu0 / eps_1)        eta_2 = np.sqrt(mu0 / eps_2)        print('eta_0')        print(eta_0)        print(' ')        print('eta_1')        print(eta_1)        print(' ')        print('eta_2')        print(eta_2)        # Cosine of the angle relative to the normal in each medium        # Snell's law is valid for lossless and lossy media:        # "Balanis' Advanced Engineering Electromagnetics", Balanis, 2024, Eqns 5-54 - 5-55b        sin_theta_0 = np.sin(theta_i)        cos_theta_0 = np.cos(theta_i)                sin_theta_1 = np.sqrt(eps_0 / eps_1) * sin_theta_0        cos_theta_1 = np.sqrt(1 - sin_theta_1**2)                   sin_theta_2 = np.sqrt(eps_1 / eps_2) * sin_theta_1        cos_theta_2 = np.sqrt(1 - sin_theta_2**2)                print(' ')        print('sin angles in layers:')        print(round(sin_theta_0,4))        print(round(sin_theta_1[0],4))        print(round(sin_theta_2[0],4))        print(' ')        print(' ')        print('cos angles in layers:')        print(round(cos_theta_0,4))        print(round(cos_theta_1[0],4))        print(round(cos_theta_2[0],4))        print(' ')                        # Complex wavenumber in lossy medium 1        k1 = omega * np.sqrt(mu0 * eps_1)                print(' ')        print('k1')        print(k1)        print(' ')                # Complex one-way phase through medium 1        phi = k1 * cos_theta_1 * d        print(' ')        print('phi')        print(phi)        print(' ')                                                                                # Fresnel coefficients                # r01,t01 for wave incident from 0 onto 1 (angle theta_0 -> theta_1)        f01 = fresnel_coeff(eta_0, eta_1, cos_theta_0, cos_theta_1, pol)        r01 = f01['r']        t01 = f01['t']        # r10,t10 for wave incident from 1 onto 0 (angle theta_1 -> theta_0)        f10 = fresnel_coeff(eta_1, eta_0, cos_theta_1, cos_theta_0, pol)        r10 = f10['r']        t10 = f10['t']                # r12,t12 for wave incident from 1 onto 2 (angle theta_1 -> theta_2)        f12 = fresnel_coeff(eta_1, eta_2, cos_theta_1, cos_theta_2, pol)        r12 = f12['r']        t12 = f12['t']                                        # Geometric series reflection        # This equation is found in:        # "Microwave Radar and Radiometric Remote Sensing", Ulaby and Long, 2014, Eqn 2.142        # "Balanis' Advanced Engineering Electromagnetics", Balanis, 2024, Eqn 5-68        # "Waves in Layered Media", L. M. Brekhovskikh, 1980, Chapter I, Eqn 3.19        # "Waves and Fields in Inhomogeneous Media", Chew, 1995, Eqn 2.1.21                #numerator = t01 * t10 * r12 * np.exp(-2j * phi)        #roundtrip = r10 * r12 * np.exp(-2j * phi)                # Sign fixed, 2026-01-24        numerator = t01 * t10 * r12 * np.exp(2j * phi)        roundtrip = r10 * r12 * np.exp(2j * phi)                rtot = r01 + numerator/(1-roundtrip)                                out = {                'rtot': rtot,                'r01':  r01,                'r10':  r10,                'r12':  r12,                't01':  t01,                't10':  t10,                't12':  t12        }                return outdef dipole_farfield(f_range, L_d, I, z_d, dipole_hat, R_m, theta_m, phi_m):                '''                DIPOLE_FARFIELD_FREQS  Far-field of Hertzian dipole over frequency range                Inputs:        f_range    - vector of frequencies (Hz), e.g. 1e6:1e6:120e6        L_d        - dipole length (m)        I          - dipole current amplitude (A phasor)        z_d        - dipole z-location (m), dipole at [0,0,z_d]                dipole_hat - 3-element cartesian unit vector for dipole orientation ([0,1,0] align with local y-axis)        R_m        - radius of moon (m), observation point is on surface        theta_s,phi_s  - angles (rad) on the moon surface at which to evaluate field (global coords)                Outputs (struct):        out.freq   - frequency array        out.E_r    - radial component (phasor) vs freq        out.E_theta, out.E_phi - tangential components (phasor) vs freq        out.E_global - 3xN array of Cartesian phasors vs freq        out.k, out.eta - arrays of wavenumber and impedance                Notes:        - Uses Hertzian dipole far-field model        - Returns phasor fields at the given (theta,phi) on the sphere                                                                # Problems?        - Electric field lacks two "-" signs        - Why transpose of Rodriges formula when converting to global?                '''                start = time.time()        c     = 299792458 # m/s        mu_0  = 4*np.pi * 1e-7        eps_0 = 1/(mu_0 * c**2)        omega = 2*np.pi*f_range                        # impedance of free space                eta_0 = np.sqrt(mu_0/eps_0)               # wavenumber in free space        k_0 = omega * np.sqrt(mu_0 * eps_0)                        # normalizing dipole orientation vector        dipole_hat = dipole_hat / np.linalg.norm(dipole_hat)                        # cartesian vector of point on the surface of the moon        r_m = R_m * np.array([np.sin(theta_m) * np.cos(phi_m), np.sin(theta_m) * np.sin(phi_m), np.cos(theta_m)])                        # cartesian vector of dipole location        r_d = np.array([0,0,z_d])                        # cartesian vector from dipole to observation point on the surface of the moon        r_i = r_m - r_d                print('r_i ---------------')        print(r_i)        print('r_i ---------------')                                                # the electric field of the dipole is first computed relative to its local coordinates        # where the dipole is aligned to local z-axis                # reference unit vector        z_local = np.array([0,0,1])                # rotation axis (axis about which dipole rotates relative to global z-axis)        v = np.cross(dipole_hat, z_local)        s = np.linalg.norm(v)                cang = np.dot(dipole_hat, z_local)                # rotation matrix        if s == 0:      # dipole already aligned with global z-axis                if cang == 1:   # parallel alignment                        ROT = np.eye(3)                   elif cang == -1:        # antiparallel alignment                        ROT = np.array([[1,0,0], [0,-1,0], [0,0,-1]])                                else:                # check this equation!!!                vx  = np.array([[0, -v[2], v[1]], [v[2], 0, -v[0]], [-v[1], v[0], 0]])                ROT = np.eye(3) + vx + np.matmul(vx,vx)*((1-cang)/(s**2))                                print('-- ROT -----')                print(ROT)                print('-----------')                                # vector from dipole to observation point, but now in local coordinates        Rvec_local = np.matmul(ROT, r_i)                print('Rvec_local ---------------------------------')        print(Rvec_local)        print('----------------------------------')        print(' ')                # local coordinates cartesian        xL = Rvec_local[0]        yL = Rvec_local[1]        zL = Rvec_local[2]                # local coordinates spherical        rL     = np.sqrt(xL**2 + yL**2 + zL**2)        thetaL = np.arccos(zL/rL)        phiL   = np.arctan2(yL, xL)           end1 = time.time()        print('Elapsed time: ' + str(np.round(end1 - start,4)) + ' s')                 # Electric field of dipole in free space in theta direction (Stutzman Eqn 1-72a)        # This equation is the far field approximation        # Note: -1j*A*exp(1jB) = 1j*A*exp(-1jB)                Etheta_local = -1j * eta_0 * (I*L_d) * (k_0/(4*np.pi*rL)) * np.sin(thetaL) * np.exp(1j*k_0*rL)                q = np.exp(1j*k_0*rL)        print('---------- Etheta ----------')        print(Etheta_local[0])        print(Etheta_local[-1])        #print(-1j*q[0])        #print(-1j*q[-1])        print('---------- Etheta ----------')                           print(len(Etheta_local))        end11 = time.time()        print('Elapsed time: ' + str(np.round(end11 - start,4)) + ' s')         # Reshaping to compute field at all frequencies simultaneously        Etheta_local_2D     = np.array([Etheta_local])        Etheta_local_column = Etheta_local_2D.reshape(-1,1)                                         #E_global_cart  = np.zeros((len(f_range),3))  +1j*0        #E_global_spher = np.zeros((len(f_range),3))  +1j*0                                        # local spherical basis vectors to cartesian coordinates (3 components)        theta_hat_local = np.array([np.cos(thetaL)*np.cos(phiL), np.cos(thetaL)*np.sin(phiL), -np.sin(thetaL)])        #phi_hat_local   = np.array([-np.sin(phiL), np.cos(phiL), 0])                theta_hat_local_2D      = np.array([theta_hat_local])        theta_hat_local_columns = np.repeat(theta_hat_local_2D, len(f_range), axis=0)                # local field to cartesian coordinates        E_local_cart_columns = theta_hat_local_columns * Etheta_local_column        # rotate back to global        E_local_cart_columns_T = np.transpose(E_local_cart_columns)        invROT = np.transpose(ROT) # the inverse of a rotation matrix is equal to its transpose        E_global_cart_columns_T = np.matmul(invROT, E_local_cart_columns_T)       # the transpose of array with complex numbers does not compute conjugate (which is what we want)        E_global_cart_columns = np.transpose(E_global_cart_columns_T)        # global spherical basis vectors at origin from cartesian to spherical coordinates (3 components)        r_hat     = np.array([np.sin(theta_m)*np.cos(phi_m), np.sin(theta_m)*np.sin(phi_m), np.cos(theta_m)])        theta_hat = np.array([np.cos(theta_m)*np.cos(phi_m), np.cos(theta_m)*np.sin(phi_m), -np.sin(theta_m)])        phi_hat   = np.array([-np.sin(phi_m), np.cos(phi_m), 0])        R_cart2spher = np.array([r_hat, theta_hat, phi_hat])                # store in spherical coordinates        E_global_spher_columns_T = np.matmul(R_cart2spher, E_global_cart_columns_T)        E_global_spher_columns   = np.transpose(E_global_spher_columns_T)                        # output        end2 = time.time()        print('Elapsed time: ' + str(np.round(end2 - start,4)) + ' s')                                out = {'eta_0' :eta_0,               'k_0'   :k_0,               'r_d'   :r_d,               'r_m'   :r_m,               'r_i'   :r_i,               'E_global_cart'  :E_global_cart_columns,               'E_global_spher' :E_global_spher_columns               }                                return outdef tests(test):        '''                Directivity of dipole in free space                '''                if test == 1:                freq = 1e6                R_ff = 1e12                Ldip = 0.5                I0 = 1                        c    = 299792458 # m/s                mu0  = 4*np.pi*1e-7                eps0 = 1/(mu0*c**2)                                k0 = 2*np.pi*freq/c                                # impedance of free space                        eta  = np.sqrt(mu0/eps0)                                                theta = np.arange(0,np.pi + 0.05*(np.pi/180), 0.1*(np.pi/180))                phi = np.arange(0,2*np.pi + 0.05*(np.pi/180), 0.1*(np.pi/180))                                Emag = np.zeros((len(theta), len(phi)))                for j in range(len(theta)):                        print(j)                        for i in range(len(phi)):                                out    = dipole_farfield(np.array([freq]), Ldip, I0, 2000, np.array([1,0,0]), R_ff, theta[j], phi[i])                                k      = out['k']                                Ecart  = out['E_global_cart']                                Espher = out['E_global_spher']                                Emag[j,i] = np.sqrt(np.sum(np.abs(Ecart[0,:])**2))                                        #U = (R_ff**2/2*eta)*Emag**2                   U = (1/(2*eta))*(R_ff**2)*Emag**2                                P_rad = (eta/(12*np.pi)) * (k0*Ldip*I0)**2                D = 4*np.pi * U / P_rad                                plt.figure()                plt.imshow(D, interpolation=None, aspect='auto');plt.colorbar()                                                        # testing theta and phi at single frequency        elif test == 2:                freq  = 1e6                #R_m   = 1734e3                #H     = 50e3                Z_dip = 1e6 #1e6 #R_m + H                R_ff  = 1e24                Ldip  = 0.5                I0    = 1                        c     = 299792458 # m/s                mu0   = 4*np.pi*1e-7                eps0  = 1/(mu0*c**2)                                k0    = 2*np.pi*freq/c                                # impedance of free space                        eta  = np.sqrt(mu0/eps0)                                                theta = np.arange(0,np.pi + 0.05*(np.pi/180), 0.01*(np.pi/180))                phi   = 0                                E = np.zeros((len(theta),3)) + 1j*0                                for j in range(len(theta)):                        #print(j)                        out     = dipole_farfield(np.array([freq]), Ldip, I0, Z_dip, np.array([1,0,0]), R_ff, theta[j], phi)                        k       = out['k']                        Ecart   = out['E_global_cart']                        Espher  = out['E_global_spher']                        #E[j,:] = Ecart[0]                        E[j,:] = Espher[0]                Emag = np.linalg.norm(E,axis=1)                                U = (1/(2*eta))*(R_ff**2)*Emag**2                                P_rad = (eta/(12*np.pi)) * (k0*Ldip*I0)**2                D = 4*np.pi * U / P_rad                                                #out = [theta*(180/np.pi), Emag, U, D]                result = [theta*(180/np.pi), Emag, U, D]        # testing radius at same frequency and coordinates                elif test == 3:                Ldip  = 0.5                I0    = 1                                freq  = 1e6                c    = 299792458 # m/s                mu0  = 4*np.pi*1e-7                eps0 = 1/(mu0*c**2)                                k0 = 2*np.pi*freq/c                                # impedance of free space                        eta  = np.sqrt(mu0/eps0)                #R_m   = 1734e3                #H     = 50e3                                Z_dip = 0 #R_m + H                                                r  = np.array([1e4])#,1e5,1e6,1e7])                                                theta = 0                phi   = 0                                E = np.zeros((len(r),3)) + 1j*0                                for j in range(len(r)):                        print(j)                        out     = dipole_farfield(np.array([freq]), Ldip, I0, Z_dip, np.array([1,0,0]), r[j], theta, phi)                        k       = out['k']                        Ecart   = out['E_global_cart']                        Espher  = out['E_global_spher']                        #E[j,:] = Ecart[0]                        E[j,:]  = Espher[0]                result = [r, E]        # testing frequency at single coordinate        elif test == 4:                Ldip  = 0.5                I0    = 1                                freq  = np.arange(1,120.00005,0.0001)                c    = 299792458 # m/s                mu0  = 4*np.pi*1e-7                eps0 = 1/(mu0*c**2)                                k0 = 2*np.pi*freq/c                                # impedance of free space                        eta  = np.sqrt(mu0/eps0)                #R_m   = 1734e3                #H     = 50e3                                Z_dip = 5e6 #R_m + H                                                r     = 1e24                        theta = 0                phi   = 0                                out     = dipole_farfield(freq, Ldip, I0, Z_dip, np.array([1,0,0]), r, theta, phi)                k       = out['k']                Ecart   = out['E_global_cart']                Espher  = out['E_global_spher']                Emag = np.linalg.norm(Espher,axis=1)                                U = (1/(2*eta))*(r**2)*Emag**2                                P_rad = (eta/(12*np.pi)) * (k0*Ldip*I0)**2                D = 4*np.pi * U / P_rad                                result = [freq, k, Espher, D]        if test == 5:                                Hdip = 50e3                R_m  = 1734e3                                z_prime  = R_m + Hdip                r_dip    = np.array([0, 0, z_prime])                theta_ff = 90*(np.pi/180)                phi_ff   = 0*(np.pi/180)                                R_hat_ff = np.array([np.sin(theta_ff)*np.cos(phi_ff), np.sin(theta_ff)*np.sin(phi_ff), np.cos(theta_ff)])                theta_s = (np.pi/180) * np.arange(0,180.00005,0.01)                phi_s   = (np.pi/180) * np.arange(0,360,1)                                metric = np.zeros((len(theta_s), len(phi_s)))                                for j in range(len(theta_s)):                        for i in range(len(phi_s)):                                                                print([j,i])                                par = [theta_s[j], phi_s[i]]                                metric[j,i] = reflected_unit_vector(par, r_dip, R_m, R_hat_ff)                result = np.copy(metric)        if test == 6:                                Hdip     = 50e3                R_m      = 1734e3                                theta_ff = 10*(np.pi/180)                phi_ff   = 170*(np.pi/180)                                                                  z_prime  = R_m + Hdip                r_dip    = np.array([0, 0, z_prime])                              #R_hat_ff = np.array([np.sin(theta_ff)*np.cos(phi_ff), np.sin(theta_ff)*np.sin(phi_ff), np.cos(theta_ff)])                                                thetax = (np.pi/180)*np.arange(0, 90.005, 0.001)                diff = np.zeros(len(thetax))                for i in range(len(thetax)):                        diff[i] = reflected_unit_vector(thetax[i], R_m, Hdip, theta_ff, phi_ff)                #theta_ub = np.arccos((R_m)/(R_m+Hdip))                result = [(180/np.pi)*thetax, diff]                        if test == 7:                                Hdip     = 5000e3                R_m      = 1734e3                theta_s_max  = np.arccos(R_m/(R_m+Hdip))                theta_ff_max = theta_s_max + (np.pi/2)                theta_ff = np.arange(0, theta_ff_max + 0.0005*(np.pi/180), 0.001*(np.pi/180))                                theta_fit = np.zeros(len(theta_ff))                for i in range(len(theta_ff)):                        print(theta_ff[i]*(180/np.pi))                        theta_fit[i] = spo.fsolve(fit_theta_of_reflected_ray_far_field, 0, args=(R_m, Hdip, theta_ff[i]), xtol=1e-9)                                result = [theta_ff, theta_fit]        return resultdef dipole_coordinates_to_global_coordinates(z_d, dip_R, dip_theta_deg, dip_phi_deg):                # cartesian vector of coordinate point relative to the dipole        dip_theta = (np.pi/180) * dip_theta_deg        dip_phi   = (np.pi/180) * dip_phi_deg                dip_r     = dip_R * np.array([np.sin(dip_theta) * np.cos(dip_phi), np.sin(dip_theta) * np.sin(dip_phi), np.cos(dip_theta)])        # cartesian vector of dipole location relative to the center of the moon        r_d = np.array([0,0,z_d])                # cartesian vector from the center of the moon to the point coordinates        # coordinates of the point when origin is the center of the moon        # we call these coordinates "global" coordinates        r = dip_r + r_d                        # global coordinates of point in spherical coordinates        x = r[0]        y = r[1]        z = r[2]                g_R     = np.sqrt((x**2) + (y**2) + (z**2))        g_theta = np.arccos(z/g_R)        g_phi   = np.arctan2(y, x)        return g_R, g_theta, g_phidef main(dip_theta_ff_deg, dip_phi_ff_deg, H_d=50e3, d=1, er_1=1, sigma_1=0, er_2=1, sigma_2=0):                R_m   = 1737.4e3        Z_d   = R_m + H_d        antenna_orientation = np.array([1,0,0])        L_d  = 0.15        I    = 1        fmin  = 1000000 #500000        fmax  = 120000000 #120499900        fstep = 100         freq  = np.arange(fmin, fmax + (fstep/2), fstep)                         omega = 2*np.pi * freq        c     = 299792458 # m/s        mu_0  = 4*np.pi * 1e-7                eps_0 = 1 / (mu_0 * c**2)        eps_1 = (eps_0 * er_1) + 1j * (sigma_1 / omega)        eps_2 = (eps_0 * er_2) + 1j * (sigma_2 / omega)        k_0   = omega * np.sqrt(mu_0 * eps_0)        eta_0 = np.sqrt(mu_0 / eps_0)        dip_R_ff = 1e12        R_ff, theta_ff, phi_ff = dipole_coordinates_to_global_coordinates(Z_d, dip_R_ff, dip_theta_ff_deg, dip_phi_ff_deg)        #R_ff     = 1e12 # m        #theta_ff = (np.pi/180) * dip_theta_ff_deg        #phi_ff   = (np.pi/180) * dip_phi_ff_deg                                                              print(' ')         print('Maximum theta of far-field point in degrees: ' + str(round((180/np.pi)*(np.pi - np.arcsin(R_m/(R_m+H_d))),3)))        print('Maximum theta of reflection point on the moon in degrees: ' + str(round((180/np.pi)*np.arccos(R_m/(R_m+H_d)),3)))                                        # Theta and phi on the surface of the moon producing a reflection toward the far field point             fit      = spo.fsolve(fit_theta_of_reflected_ray_far_field, 0, args=(R_m, H_d, theta_ff), xtol=1e-9)        theta_m  = fit[0]        phi_m    = np.copy(phi_ff)                # Angle of the point on the moon in degrees        print('Coordinates of reflection point on the moon in degrees (theta, phi): ' + str(round((180/np.pi)*theta_m,3)) + ', ' + str((180/np.pi)*phi_m))        print('')                        # E-field and vectors on the surface of the moon        out   = dipole_farfield(freq, L_d, I, Z_d, antenna_orientation, R_m, theta_m, phi_m)        r_d   = out['r_d']  # vector from global origin to dipole        r_m   = out['r_m']  # vector from global origin to moon surface        r_i   = out['r_i']  # vector from dipole to moon surface        Ecart  = out['E_global_cart']                Espher = out['E_global_spher']                print(' ')        print('------- Ecart --------')        print(Ecart[0])        print(Ecart[-1])        print('------- Ecart --------')        print(' ')                print(' ')        print('------- Espher --------')        print(Espher[0])        print(Espher[-1])        print('------- Espher --------')        print(' ')                                # S and P polarizations of E-field        r_m_hat = r_m / np.linalg.norm(r_m)        r_i_hat = r_i / np.linalg.norm(r_i)        out2  = decompose_sp(Ecart, r_i, r_m)        E_s   = out2['E_s']        E_p   = out2['E_p']        s_hat = out2['s_hat']        p_hat_refl = out2['p_hat_refl']                        print('r_i_hat')        print(r_i_hat)        print(' ')                print('r_m_hat')        print(r_m_hat)        print(' ')                                print('s_hat and p_hat_refl')        print(s_hat)        print(p_hat_refl)        print(' ')                print(' ')        print('E_s and E_p:')        print(E_s[0:2])        print(E_p[0:2])                        # Angle of incidence of incoming ray at the surface of the moon        theta_i = np.arccos(np.abs(np.dot(r_i_hat, r_m_hat)))        print(' ')        print('Angle of incidence in degrees: ' + str(round((180/np.pi)*theta_i,3)))                        # Reflection coefficients        out3_s = total_reflection_three_layers(freq, eps_0, eps_1, eps_2, theta_i, d, 's')        out3_p = total_reflection_three_layers(freq, eps_0, eps_1, eps_2, theta_i, d, 'p')                rtot_s = out3_s['rtot']        rtot_p = out3_p['rtot']                print(' ')        print('Ref. Trans. Coeff - S:')        print(round(out3_s['rtot'][0],4))        print(round(out3_s['r01'][0],4))        print(round(out3_s['r10'][0],4))        print(round(out3_s['r12'][0],4))        print(round(out3_s['t01'][0],4))        print(round(out3_s['t10'][0],4))        print(round(out3_s['t12'][0],4))        print(' ')                print(' ')        print('Ref. Trans. Coeff - P:')        print(round(out3_p['rtot'][0],4))        print(round(out3_p['r01'][0],4))        print(round(out3_p['r10'][0],4))        print(round(out3_p['r12'][0],4))        print(round(out3_p['t01'][0],4))        print(round(out3_p['t10'][0],4))        print(round(out3_p['t12'][0],4))        print(' ')                                # Total reflected E-field at the surface of the moon on the side of medium 0        E_refl_s = np.repeat(np.array([rtot_s * E_s]).T, len(s_hat), axis=1)        E_refl_p = np.repeat(np.array([rtot_p * E_p]).T, len(p_hat_refl), axis=1)                print(' ')        print('----------- E_refl_s -----------------')        print(E_refl_s[0,:])        print(E_refl_s[-1,:])        print('--------------------------------------')        print(' ')        print(' ')        print('----------- E_refl_p -----------------')        print(E_refl_p[0,:])        print(E_refl_p[-1,:])        print('--------------------------------------')        print(' ')                # Now using p_hat_refl (correction applied in decompose_sp)        # ---------------------------------------------------------        E_refl = (E_refl_s * s_hat) + (E_refl_p * p_hat_refl)        print(' ')        print('----------- E_refl -----------------')        print(E_refl[0,:])        print(E_refl[-1,:])        print('--------------------------------------')        print(' ')                         # Reflected E-field projected to the far field                # Vector from global origin to far field point        r_ff_hat = np.array([np.sin(theta_ff) * np.cos(phi_ff), np.sin(theta_ff) * np.sin(phi_ff), np.cos(theta_ff)])        r_ff     = R_ff * r_ff_hat        print(' ')        print('-------------')        print(' r_ff ')        print(r_ff)        print('-------------')        print(' ')                        # Distance from specular emission on the surface of the moon to far field point        dist_moon_FF = np.linalg.norm(r_ff - r_m)         print(' ')        print('-------------')        print(' dist_moon_FF ')        print(dist_moon_FF)        print('-------------')        print(' ')                        # Amplitude normalization shifted to antenna (Aditya's version)        #A = np.linalg.norm(r_i) / (4*np.pi * (R_ff - R_m + np.linalg.norm(r_i)))           # Amplitude normalization shifted to antenna (Raul's version)        # A = np.linalg.norm(r_i) / (4*np.pi * (dist_moon_FF + np.linalg.norm(r_i)))                   # Amplitude normalization shifted to antenna (Raul's version 2, without the 4 pi)        A = np.linalg.norm(r_i) / (dist_moon_FF + np.linalg.norm(r_i))                # Today (2026-04-06)        dist_dip_moon = np.linalg.norm(r_i)        rho1 = (R_m*dist_dip_moon*np.cos(theta_i)) / (R_m*np.cos(theta_i) + 2*dist_dip_moon)        rho2 = (R_m*dist_dip_moon) / (R_m + 2*dist_dip_moon*np.cos(theta_i))        Div = np.sqrt((rho1*rho2)/((rho1 + dist_moon_FF)*(rho2 + dist_moon_FF)))                                                                # The two normalizations produce "almost" identical results, insignificant difference        print(' ')        print('-------------')        print(' A ')        print(A)        print('-------------')        print(' ')                        print(' ')        print('-------------')        print(' k_0 ')        print(k_0)        print('-------------')        print(' ')                X = 1j * k_0 * dist_moon_FF        print(' ')        print('----------- X -----------------')        print(X[0])        print(X[-1])        print('--------------------------------------')        print(' ')                #E_refl_ff_T = A * E_refl.T * np.exp(1j * k_0 * dist_moon_FF)        #E_refl_ff   = E_refl_ff_T.T        #print(' ')        #print('----------- E_refl_ff -----------------')        #print(E_refl_ff[0,:])        #print(E_refl_ff[-1,:])        #print('--------------------------------------')        #print(' ')        # Today (2026-04-06)        E_refl_ff_T = Div * E_refl.T * np.exp(1j * k_0 * dist_moon_FF)        E_refl_ff  = E_refl_ff_T.T                                        # Direct E-field at the far field        out4  = dipole_farfield(freq, L_d, I, Z_d, antenna_orientation, R_ff, theta_ff, phi_ff)        E_dir_ff = out4['E_global_cart']        print(' ')        print('----------- E_dir_ff -----------------')        print(E_dir_ff[0,:])        print(E_dir_ff[-1,:])        print('--------------------------------------')        print(' ')                        # Total E-field at the far field         E_tot_ff = E_dir_ff + E_refl_ff                                        #E_tot_ff = E_dir_ff        #E_tot_ff = E_refl_ff        print(' ')        print('----------- E_tot_ff -----------------')        print(E_tot_ff[0,:])        print(E_tot_ff[-1,:])        print('--------------------------------------')        print(' ')                        # Magnitude of total E-field        E_mag = np.linalg.norm(E_tot_ff, axis=1) # Norm-2 of cartesian complex vector        print(' ')        print('----------- E_mag -----------------')        print(E_mag)        print('--------------------------------------')        print(' ')                                # Distance from dipole to far field point        dist_dipole_FF = np.linalg.norm(r_ff - r_d)        print(' ')        print('-------------')        print(' dist_dipole_FF ')        print(dist_dipole_FF)        print('-------------')        print(' ')                        # Radiation intensity        #U = ((dist_moon_FF**2)/(2 * eta_0)) * E_mag**2                U = ((dist_dipole_FF**2)/(2 * eta_0)) * E_mag**2                #E_dir_ff_mag  = np.linalg.norm(E_dir_ff, axis=1)        #E_refl_ff_mag = np.linalg.norm(E_refl_ff, axis=1)        #U = (1/(2 * eta_0)) * (  (dist_dipole_FF * E_dir_ff_mag)**2  +  ((dist_moon_FF ) * E_refl_ff_mag)**2  )        print(' ')        print('-------------')        print(' U ')        print(U)        print('-------------')        print(' ')                      #U = ((R_ff**2)/(2 * eta_0)) * E_mag**2                # The three distances are about the same, but the distance to the FF from the dipole and the moon are about the same and more accurate (the distance from the center of the Moon is farther away and less representative).        # We use the distance from dipole to FF.                        # Radiated power        P_rad = (eta_0/(12*np.pi)) * (k_0 * L_d * I)**2        print(' ')        print('-------------')        print(' P_rad ')        print(P_rad)        print('-------------')        print(' ')                                                        # Directivity        D = 4*np.pi * U / P_rad        print(' ')        print('-------------')        print(' D ')        print(D)        print('-------------')        print(' ')                                                                                                  f_MHz = freq/1e6        # Frequency binning        #D_2D = np.array([D[0:-1]])  # excise the last point        #x = D_2D.reshape((119,int((len(f_MHz)-1)/119)))   # create 119 bins        #D_av = np.mean(x, axis=1)  # average 119 bins                #f_2D = np.array([f_MHz[0:-1]])        #x = f_2D.reshape((119,int((len(f_MHz)-1)/119)))        #f_av = np.mean(x, axis=1)  # average 119 bins                                                                # New calculation for Poynting vector on the surface of the Moon                                # Incident magnetic field        Hcart = (1/eta_0) * np.cross(r_i_hat, Ecart)                # Normalized vector of reflected direction        r_refl_hat = (r_ff - r_m)/dist_moon_FF                        # Reflected magnetic field        H_refl = (1/eta_0) * np.cross(r_refl_hat, E_refl)                # Total E- and H-fields on the surface        E_tot_surf = Ecart + E_refl        H_tot_surf = Hcart + H_refl                # Complex conjugate of H-field        H_tot_surf_cc = np.conjugate(H_tot_surf)                # Time-averaged power density (Poynting vector)        Svec = (1/2) * np.real(np.cross(E_tot_surf, H_tot_surf_cc))                # Component of Poynting vector normal to Moon's surface        Snormal = np.dot(Svec, r_m_hat)     # Computed in cartesian coordinates, produces (Nv x 1) array                 # To do        # Compute numerical integral:        # P_abs = - \int_phi \int_theta Svec_normal * (r_moon)^2 * sin(theta_moon) * (d_theta_moon) * (d_phi_moon)                        #print([dist_dip_moon, (180/np.pi)*theta_i, np.cos(theta_i), Div])                        U_soil = -(R_m**2) * Snormal                norm_e_si = np.linalg.norm(Ecart, axis=1) # Norm-2 of cartesian complex vector                norm_s_si = (1/(2 * eta_0)) * norm_e_si**2        norm_s_st = np.linalg.norm(Svec, axis=1) # Norm-2 of cartesian complex vector                        print([f_MHz[0], Hcart[0]])                return f_MHz, E_refl, E_refl_ff, E_dir_ff, E_tot_ff, E_mag, U, P_rad, D, rtot_s, rtot_p, Ecart, Svec, Snormal, U_soil, norm_s_si, norm_s_stdef main_toward_moon(theta_m_deg, phi_m_deg):                #R_ff  = 1e12 # m                R_m   = 1737.4e3        H_d   = 50000        Z_d   = R_m + H_d        theta_m = (np.pi/180) * theta_m_deg        phi_m   = (np.pi/180) * phi_m_deg                              theta_s_max = np.arccos(R_m/(R_m + H_d))                if theta_m < theta_s_max:                                antenna_orientation = np.array([1,0,0])                L_d  = 0.5                I    = 1                                        d = 10                        er_1    = 3                sigma_1 = 0.0002                                er_2    = 8                sigma_2 = 0.001                                        fmin  = 1e6                fmax  = 120e6                fstep = 100                 freq  = np.arange(fmin, fmax + (fstep/2), fstep)                                                          omega = 2*np.pi * freq                c     = 299792458 # m/s                mu_0  = 4*np.pi * 1e-7                        eps_0 = 1 / (mu_0 * c**2)                eps_1 = (eps_0 * er_1) - 1j * (sigma_1 / omega)                eps_2 = (eps_0 * er_2) - 1j * (sigma_2 / omega)                k_0   = omega * np.sqrt(mu_0 * eps_0)                eta_0 = np.sqrt(mu_0 / eps_0)                                                                                                                              # Theta and phi on the surface of the moon producing a reflection toward the far field point                #theta_ff = (np.pi/180) * theta_ff_deg                #phi_ff   = (np.pi/180) * phi_ff_deg                        #fit      = spo.fsolve(fit_theta_of_reflected_ray_far_field, 0, args=(R_m, H_d, theta_ff), xtol=1e-9)                #theta_m  = fit[0]                #phi_m    = np.copy(phi_ff)                                                                                                          # E-field and vectors incident on the surface of the moon                out   = dipole_farfield(freq, L_d, I, Z_d, antenna_orientation, R_m, theta_m, phi_m)                r_m   = out['r_m']  # vector from global origin to moon surface                r_i   = out['r_i']  # vector from dipole to moon surface                E_inc = out['E_global_cart']                                                        # S and P polarizations of E-field                r_m_hat = r_m / np.linalg.norm(r_m)                r_i_hat = r_i / np.linalg.norm(r_i)                out2  = decompose_sp(E_inc, r_i, r_m)                E_s   = out2['E_s']                E_p   = out2['E_p']                s_hat = out2['s_hat']                p_hat = out2['p_hat']                                                # Angle of incidence of incoming ray at the surface of the moon                theta_i = np.arccos(np.abs(np.dot(r_i_hat, r_m_hat)))                                                # Reflection coefficients                out3_s = total_reflection_three_layers(freq, eps_0, eps_1, eps_2, theta_i, d, 's')                out3_p = total_reflection_three_layers(freq, eps_0, eps_1, eps_2, theta_i, d, 'p')                        rtot_s = out3_s['rtot']                rtot_p = out3_p['rtot']                                                # Total reflected E-field at the surface of the moon on the side of medium 0                E_refl_s = np.repeat(np.array([rtot_s * E_s]).T, len(s_hat), axis=1)                E_refl_p = np.repeat(np.array([rtot_p * E_p]).T, len(p_hat), axis=1)                E_refl = (E_refl_s * s_hat) + (E_refl_p * p_hat)                                                                                         ## Reflected E-field projected to the far field                                ## Vector from global origin to far field point                #r_ff_hat = np.array([np.sin(theta_ff) * np.cos(phi_ff), np.sin(theta_ff) * np.sin(phi_ff), np.cos(theta_ff)])                #r_ff     = R_ff * r_ff_hat                                                ## Distance from specular emission on the surface of the moon to the far field point                ##d_ff = np.linalg.norm(r_ff - r_m)                ##E_refl_ff_T = E_refl.T * np.exp(1j * k_0 * d_ff) / (4*np.pi * d_ff)                                #A = R_ff - np.dot(r_m, r_ff_hat)                #B = 4*np.pi * (R_ff - R_m + np.linalg.norm(r_i)) / np.linalg.norm(r_i)                #E_refl_ff_T = E_refl.T * np.exp(1j * k_0 * A) / B                        #E_refl_ff   = E_refl_ff_T.T                                                                ## Direct E-field at the far field                #out4  = dipole_farfield(freq, Ldip, I0, Z_d, antenna_orientation, R_ff, theta_ff, phi_ff)                #E_dir_ff = out4['E_global_cart']                                                                                                                                                # Total E-field at the far field                 E_tot = E_inc + E_refl                                                # Radiation intensity                E_mag = np.linalg.norm(E_tot, axis=1)                distance2moon = np.linalg.norm(r_i)                U = ((distance2moon**2)/(2 * eta_0)) * E_mag**2                                                # Directivity                P_rad = (eta_0/(12*np.pi)) * (k_0 * L_d * I)**2                D = 4*np.pi * U / P_rad                f_MHz = freq/1e6                                        # Frequency binning                D_2D = np.array([D[0:-1]])  # excise the last point                x = D_2D.reshape((119,int((len(f_MHz)-1)/119)))   # create 119 bins                D_av = np.mean(x, axis=1)  # average 119 bins                                f_2D = np.array([f_MHz[0:-1]])                x = f_2D.reshape((119,int((len(f_MHz)-1)/119)))                f_av = np.mean(x, axis=1)  # average 119 bins                                        else:                print('theta too large')                f_MHz = 0                E_inc = 0                E_refl = 0                D = 0                f_av = 0                D_av = 0                                return f_MHz, E_inc, E_refl, D, f_av, D_av